const toolbar=document.createElement('div');toolbar.className='home-toolbar';toolbar.innerHTML='<button type="button" class="btn" id="homeCustomize" aria-expanded="false" aria-controls="homeSettings">✧ Meu cantinho</button><button type="button" class="btn" id="homeCompose">♡ Criar bilhete</button>';hp('hubLogout').before(toolbar);toolbar.append(hp('hubLogout'));
const settings=document.createElement('section');settings.id='homeSettings';settings.className='home-settings';settings.hidden=true;settings.innerHTML=`<div class="home-section-heading"><div><span class="hub-brand">DO SEU JEITO</span><h2>Meu cantinho</h2></div><button type="button" class="btn" id="homeSettingsClose">Fechar</button></div><form id="homeSettingsForm"><div class="home-form-row"><div><label for="homeName">Nome do seu painel</label><input id="homeName" maxlength="35" placeholder="Aliny Flow"></div><div><label for="homePalette">Cores do seu cantinho</label><select id="homePalette">${Object.entries(homePalettes).map(([key,value])=>`<option value="${key}">${value.name}</option>`).join('')}</select></div></div><label for="homeWelcome">Sua frase de boas-vindas</label><input id="homeWelcome" maxlength="90" placeholder="Deixe vazio para manter a saudação do horário"><div class="home-actions"><button type="submit" class="home-primary home-write">Aplicar e salvar na minha conta</button><button type="button" id="homeRestore" class="btn home-write">Usar visual original</button></div><p class="home-small">Personaliza esta página inicial. O nome dos aplicativos e os temas do login continuam disponíveis.</p><p id="homeSettingsStatus" role="status"></p></form>`;
