const cardDialog=document.createElement('dialog');cardDialog.id='homeCardDialog';cardDialog.innerHTML=`<div class="home-section-heading"><div><span class="hub-brand">UM CARINHO COM A SUA ASSINATURA</span><h2>Bilhetes para quem eu amo</h2></div><button type="button" class="btn" id="homeCardClose" aria-label="Fechar criador de bilhetes">✕</button></div><p class="home-small">Escreva, baixe o cartão e envie pelo aplicativo que você preferir.</p><div class="home-card-grid"><form id="homeCardForm"><label for="homeCardTo">Para quem? (opcional)</label><input id="homeCardTo" maxlength="40" placeholder="Para alguém especial"><label for="homeCardMessage">Seu bilhete</label><textarea id="homeCardMessage" required maxlength="600" rows="6" placeholder="Tem um carinho meu guardado nessas palavras…"></textarea><label for="homeCardFrom">Sua assinatura (opcional)</label><input id="homeCardFrom" maxlength="40" placeholder="Com carinho…"><label for="homeCardPalette">Cores do cartão</label><select id="homeCardPalette"><option value="violet">Lilás e encanto</option><option value="rose">Rosa e afeto</option><option value="night">Azul e estrelas</option><option value="sage">Verde e calma</option></select><div class="home-actions"><button type="submit" class="home-primary">↓ Baixar cartão PNG</button></div><p class="home-small">Imagem de 1.080 × 1.350 pixels. O bilhete não é enviado nem salvo na conta; o rascunho é apagado ao fechar.</p><p id="homeCardStatus" role="status"></p></form><canvas id="homeCardCanvas" width="1080" height="1350" role="img" aria-label="Prévia do bilhete"></canvas></div>`;hub.append(cardDialog);
