function setHomeBusy(value){homeBusy=value;for(const button of hub.querySelectorAll('.home-write'))button.disabled=value||!homeLoaded;}
function homePrefs(){const value=homeData.home||{};return {name:typeof value.name==='string'?value.name.slice(0,35):'',welcome:typeof value.welcome==='string'?value.welcome.slice(0,90):'',palette:Object.hasOwn(homePalettes,value.palette)?value.palette:'violet'};}
function applyHomePreferences(){const prefs=homePrefs(),palette=homePalettes[prefs.palette];for(const key of ['accent','bg','card','border'])hub.style.setProperty('--home-'+key,palette[key]);const label=hub.querySelector('.hub-top>.hub-brand>span:last-child');label.replaceChildren(document.createTextNode(prefs.name||'ALINY FLOW'));const small=document.createElement('small');small.textContent='seu universo em um só lugar';label.append(small);if(prefs.welcome)hp('hubTitle').textContent=prefs.welcome;}
function homeDateLabel(date){return /^\d{4}-\d{2}-\d{2}$/.test(date)?new Date(date+'T12:00:00').toLocaleDateString('pt-BR'):'';}
function ritualItems(){return Array.isArray(homeData.rituals)?homeData.rituals.filter(item=>item&&typeof item.date==='string'&&Object.hasOwn(rituals,item.mood)&&typeof item.plan==='string'):[];}
function playlistUrl(text){if(!text?.trim())return '';let value;try{value=new URL(text.trim());}catch{throw Error('Cole o link completo da playlist do Spotify.');}const match=value.pathname.match(/^\/(?:intl-[a-z]{2}\/)?playlist\/([A-Za-z0-9]{22})\/?$/);if(value.protocol!=='https:'||value.hostname!=='open.spotify.com'||value.username||value.password||!match)throw Error('Use um link de playlist em open.spotify.com/playlist/…');return 'https://open.spotify.com/playlist/'+match[1];}
function updateRitualMusic(){const link=hp('homeRitualMusic'),value=hp('homeRitualSpotify').value.trim();try{const url=playlistUrl(value);if(url){link.href=url;link.target='_blank';link.rel='noopener';link.textContent='Ouvir minha playlist no Spotify ↗';hp('homeRitualMusicHint').textContent='A playlist escolhida por você para acompanhar este ritual.';}else{link.href='./music.html?moment='+rituals[ritualMood].moment+(ritualMood==='focus'?'&focus=1':'');link.removeAttribute('target');link.removeAttribute('rel');link.textContent=ritualMood==='focus'?'Abrir música e modo foco →':'Escolher / ouvir no Aliny Music →';hp('homeRitualMusicHint').textContent='Use suas músicas locais ou as playlists que você associou ao seu momento.';}}catch{link.href='./music.html';link.removeAttribute('target');link.textContent='Abrir Aliny Music →';hp('homeRitualMusicHint').textContent='Revise o link da playlist ou escolha suas músicas no Aliny Music.';}}
function renderRitual(){for(const button of hub.querySelectorAll('[data-home-mood]'))button.setAttribute('aria-pressed',String(button.dataset.homeMood===ritualMood));hp('homeRitualQuote').textContent=rituals[ritualMood].quote;hp('homeRitualDate').textContent=homeDateLabel(ritualDate);const todayItem=ritualItems().find(item=>item.date===ritualDate),done=!!todayItem?.done&&todayItem.mood===ritualMood&&todayItem.plan===hp('homeRitualPlan').value.trim();hp('homeRitualDone').setAttribute('aria-pressed',String(done));hp('homeRitualDone').textContent=done?'✓ Passo feito · desfazer':'Marcar meu passo como feito';updateRitualMusic();hp('homeRitualHistory').innerHTML=!homeLoaded?'<p class="home-small">Carregue seu ritual para ver o histórico.</p>':ritualItems().length?ritualItems().slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,9).map(item=>`<article class="home-ritual-past"><time datetime="${escapePreview(item.date)}">${escapePreview(homeDateLabel(item.date))}</time><b>${rituals[item.mood].icon} ${rituals[item.mood].name}</b><p>${escapePreview(item.plan)}</p><small>${item.done?'✓ Passo realizado':'Um plano guardado'}</small></article>`).join(''):'<p class="home-small">Seus próximos rituais vão aparecer aqui.</p>';setHomeBusy(homeBusy);}
function fillRitual(){ritualDate=homeToday();const item=ritualItems().find(item=>item.date===ritualDate);ritualMood=item?.mood||'rest';hp('homeRitualPlan').value=item?.plan||rituals[ritualMood].suggestion;hp('homeRitualSpotify').value=typeof item?.playlist==='string'?item.playlist:'';renderRitual();}
async function loadPersonalHome(){if(homeBusy)return;const request=++homeRequest;homeLoaded=false;setHomeBusy(true);hp('homeRitualStatus').textContent='Buscando seu ritual na sua conta…';try{await window.alinyAuth.ready;const response=await window.alinyAuth.api('/api/inspira',{method:'GET'});if(!response.ok)throw Error('Não consegui carregar seu cantinho. Clique em Atualizar resumo para tentar novamente.');const result=await response.json();if(request!==homeRequest||document.body.classList.contains('auth-locked'))return;homeData=result.data&&typeof result.data==='object'&&!Array.isArray(result.data)?result.data:{};homeRevision=result.revision;homeLoaded=true;updateGreeting(new Date());if(!ritualDirty)fillRitual();else renderRitual();hp('homeRitualStatus').textContent='Ritual e preferências sincronizados com sua conta.';}catch(error){if(request===homeRequest)hp('homeRitualStatus').textContent=error.message;}finally{if(request===homeRequest)setHomeBusy(false);}}
async function savePersonalHome(change,message){if(homeBusy||!homeLoaded){message.textContent='Aguarde a sincronização ou clique em Atualizar resumo. Seu texto continua aqui.';return false;}const request=homeRequest;setHomeBusy(true);message.textContent='Guardando na sua conta…';try{const next=JSON.parse(JSON.stringify(homeData));change(next);const response=await window.alinyAuth.api('/api/inspira',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:homeRevision,data:next})});if(request!==homeRequest||document.body.classList.contains('auth-locked'))return false;if(response.status===409){homeLoaded=false;throw Error('Sua conta mudou em outro cantinho ou dispositivo. Atualize o resumo e tente novamente. Seu rascunho continua aqui.');}if(!response.ok)throw Error('Não consegui salvar online. Seu texto continua aqui para você tentar de novo.');const result=await response.json();if(request!==homeRequest)return false;homeData=next;homeRevision=result.revision;if(message.id==='homeRitualStatus')ritualDirty=false;updateGreeting(new Date());renderRitual();message.textContent='Guardado na sua conta. 💜';return true;}catch(error){if(request===homeRequest)message.textContent=error.message;return false;}finally{if(request===homeRequest)setHomeBusy(false);}}
hp('homeCustomize').onclick=()=>{settings.hidden=!settings.hidden;hp('homeCustomize').setAttribute('aria-expanded',String(!settings.hidden));if(!settings.hidden){const prefs=homePrefs();hp('homeName').value=prefs.name;hp('homeWelcome').value=prefs.welcome;hp('homePalette').value=prefs.palette;hp('homeName').focus();}};
hp('homeSettingsClose').onclick=()=>{settings.hidden=true;hp('homeCustomize').setAttribute('aria-expanded','false');hp('homeCustomize').focus();};
hp('homeSettingsForm').onsubmit=async e=>{e.preventDefault();const prefs={name:hp('homeName').value.trim(),welcome:hp('homeWelcome').value.trim(),palette:hp('homePalette').value};await savePersonalHome(next=>next.home=prefs,hp('homeSettingsStatus'));};
hp('homeRestore').onclick=async()=>{if(await savePersonalHome(next=>next.home={name:'',welcome:'',palette:'violet'},hp('homeSettingsStatus'))){hp('homeName').value='';hp('homeWelcome').value='';hp('homePalette').value='violet';updateGreeting(new Date());}};
ritualSection.querySelector('.home-ritual-moods').onclick=e=>{const button=e.target.closest('[data-home-mood]');if(!button)return;const previous=rituals[ritualMood].suggestion;ritualMood=button.dataset.homeMood;ritualDirty=true;if(!hp('homeRitualPlan').value.trim()||hp('homeRitualPlan').value===previous)hp('homeRitualPlan').value=rituals[ritualMood].suggestion;renderRitual();};
hp('homeRitualSpotify').oninput=()=>{ritualDirty=true;updateRitualMusic();};hp('homeRitualPlan').oninput=()=>{ritualDirty=true;renderRitual();};
function ritualDraft(){const plan=hp('homeRitualPlan').value.trim();if(!plan)throw Error('Escolha um pequeno plano para o seu ritual.');return {date:homeToday(),mood:ritualMood,plan,playlist:playlistUrl(hp('homeRitualSpotify').value)};}
hp('homeRitualForm').onsubmit=async e=>{e.preventDefault();try{const item=ritualDraft();ritualDate=item.date;await savePersonalHome(next=>{const items=Array.isArray(next.rituals)?next.rituals:[],previous=items.find(value=>value?.date===item.date);if(!previous&&items.length>=1000)throw Error('Você já guardou 1.000 rituais. Pode continuar atualizando o de hoje.');next.rituals=[{...item,done:previous?.plan===item.plan&&previous?.mood===item.mood?!!previous.done:false},...items.filter(value=>value?.date!==item.date)];},hp('homeRitualStatus'));}catch(error){hp('homeRitualStatus').textContent=error.message;}};
hp('homeRitualDone').onclick=async()=>{try{const draft=ritualDraft();ritualDate=draft.date;await savePersonalHome(next=>{const items=Array.isArray(next.rituals)?next.rituals:[],previous=items.find(value=>value?.date===draft.date);if(!previous&&items.length>=1000)throw Error('Você já guardou 1.000 rituais.');next.rituals=[{...draft,done:previous?.plan===draft.plan&&previous?.mood===draft.mood?!previous.done:true},...items.filter(value=>value?.date!==draft.date)];},hp('homeRitualStatus'));}catch(error){hp('homeRitualStatus').textContent=error.message;}};
hp('homeRitualHistoryToggle').onclick=()=>{const list=hp('homeRitualHistory');list.hidden=!list.hidden;hp('homeRitualHistoryToggle').setAttribute('aria-expanded',String(!list.hidden));};
function closePersonalHome(){homeRequest++;homeBusy=false;if(cardDialog.open)cardDialog.close();}
function resetPersonalHome(){closePersonalHome();homeData={};homeRevision=0;homeLoaded=false;ritualDirty=false;settings.hidden=true;hp('homeCustomize').setAttribute('aria-expanded','false');hp('homeSettingsForm').reset();hp('homeSettingsStatus').textContent='';hp('homeRitualStatus').textContent='';hp('homeRitualHistory').hidden=true;hp('homeRitualHistoryToggle').setAttribute('aria-expanded','false');applyHomePreferences();fillRitual();hp('homeCardForm').reset();drawHomeCard();}
new MutationObserver(()=>{if(document.body.classList.contains('auth-locked'))resetPersonalHome();}).observe(document.body,{attributes:true,attributeFilter:['class']});
const cardInk={violet:['#f0e7f5','#ddc8ee','#3e284f','#80618f'],rose:['#faecea','#efd0d5','#5c3146','#a4707f'],night:['#102439','#294765','#e8f1ff','#a8cbe5'],sage:['#e9eee2','#cbdac2','#29433b','#668071']};
function cardLines(ctx,text,width){const lines=[];for(const paragraph of text.split('\n')){let line='';for(const word of paragraph.trim().split(/\s+/)){if(!word)continue;const trial=line?line+' '+word:word;if(ctx.measureText(trial).width<=width){line=trial;continue;}if(line){lines.push(line);line='';}if(ctx.measureText(word).width<=width){line=word;continue;}for(const char of word){if(line&&ctx.measureText(line+char).width>width){lines.push(line);line=char;}else line+=char;}}lines.push(line);}return lines;}
let homeCardFits=true;
function drawHomeCard(){const canvas=hp('homeCardCanvas'),ctx=canvas.getContext('2d'),palette=cardInk[hp('homeCardPalette').value]||cardInk.violet,[bg,detail,ink,muted]=palette;ctx.fillStyle=bg;ctx.fillRect(0,0,1080,1350);const gradient=ctx.createRadialGradient(1080,0,30,1080,0,850);gradient.addColorStop(0,detail);gradient.addColorStop(1,bg);ctx.fillStyle=gradient;ctx.fillRect(0,0,1080,1350);ctx.strokeStyle=muted;ctx.globalAlpha=.28;ctx.lineWidth=2;ctx.strokeRect(45,45,990,1260);for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(1050,90,170+i*75,0,Math.PI*2);ctx.stroke();}ctx.globalAlpha=1;ctx.fillStyle=muted;ctx.font='21px system-ui';ctx.fillText('UM BILHETINHO COM CARINHO',90,125);ctx.fillStyle=ink;ctx.font='52px Georgia';const to=hp('homeCardTo').value.trim()||'Para alguém especial';const headings=cardLines(ctx,to,900);for(let i=0;i<Math.min(2,headings.length);i++)ctx.fillText(headings[i],90,245+i*64);const text=hp('homeCardMessage').value.trim()||'Tem um carinho meu guardado nessas palavras…';let size=46,lines;do{ctx.font=size+'px Georgia';lines=cardLines(ctx,text,900);size-=1;}while(lines.length*(size+1)*1.5>700&&size>17);const lineHeight=(size+1)*1.5;homeCardFits=lines.length*lineHeight<=700;ctx.save();ctx.beginPath();ctx.rect(85,350,920,780);ctx.clip();let y=400;for(const line of lines){ctx.fillText(line,90,y);y+=lineHeight;}ctx.restore();ctx.fillStyle=muted;ctx.font='29px Georgia';const from=hp('homeCardFrom').value.trim()||'Com carinho, para você.';const signature=cardLines(ctx,from,900);for(let i=0;i<Math.min(2,signature.length);i++)ctx.fillText(signature[i],90,1190+i*39);ctx.font='18px system-ui';ctx.fillText('ALINY FLOW  ·  UM GESTO DE AFETO',90,1290);canvas.setAttribute('aria-label','Prévia do cartão: '+to);}
hp('homeCompose').onclick=()=>{drawHomeCard();cardDialog.showModal();hp('homeCardTo').focus();};hp('homeCardClose').onclick=()=>cardDialog.close();cardDialog.addEventListener('close',()=>{hp('homeCardForm').reset();hp('homeCardStatus').textContent='';drawHomeCard();});for(const id of ['homeCardTo','homeCardMessage','homeCardFrom','homeCardPalette'])hp(id).oninput=drawHomeCard;
hp('homeCardForm').onsubmit=e=>{e.preventDefault();if(!hp('homeCardMessage').value.trim()){hp('homeCardStatus').textContent='Escreva seu bilhete antes de baixar.';return;}drawHomeCard();if(!homeCardFits){hp('homeCardStatus').textContent='Encurte o bilhete ou reduza as quebras de linha para caber no cartão.';return;}hp('homeCardCanvas').toBlob(blob=>{if(!blob){hp('homeCardStatus').textContent='Não consegui gerar a imagem. Tente novamente.';return;}const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='bilhete-aliny-flow.png';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);hp('homeCardStatus').textContent='Cartão pronto para baixar. Envie por onde preferir. 💜';},'image/png');};
hp('hubDayRefresh').onclick=()=>{refreshDay();loadPersonalHome();};
